#include <linux/sched.h>
#include <linux/uaccess.h>

int set_ext_regs(struct task_struct *child, void __user *uregs)
{
    int ret = 0;

    if (uregs) {
        if (!access_ok(uregs, sizeof(*uregs)))
            return -EFAULT;

        /* Flush and release coprocessors if applicable */
        unlazy_fpu(child);

        /* Copy extended register values from user space */
        if (copy_from_user(&child->thread.ext_regs, uregs, sizeof(child->thread.ext_regs))) {
            ret = -EFAULT;
        }
    }

    return ret;
}

int set_ext_register(struct task_struct *child, void __user *uregs)
{
    if (!access_ok(uregs, sizeof(struct user_regset)))
        return -EFAULT;

    if (need_flush_userregs())
        flush_userregs();

    if (copy_from_user(&child->thread.ext_regs, uregs, sizeof(struct user_regset)))
        return -EFAULT;

    return 0;
}

#include <linux/sched.h>
#include <linux/uaccess.h>

int set_task_extended_regs(struct task_struct *child, void __user *uregs)
{
    int ret = 0;

    if (!access_ok(uregs, sizeof(*uregs)))
        return -EFAULT;

    /* Flush and release coprocessors if applicable */
    unlazy_fpu(child);

    if (copy_from_user(&child->thread.extregs, uregs, sizeof(child->thread.extregs))) {
        ret = -EFAULT;
    }

    return ret;
}

int set_ext_register(struct task_struct *child, void __user *uregs)
{
    int ret = 0;

    if (!access_ok(uregs, sizeof(struct extended_regs)))
        return -EFAULT;

    /* Flush and release coprocessors if applicable */
    release_user_return_thunk();

    ret = copy_from_user(&child->thread.ext_regs, uregs, sizeof(struct extended_regs));
    if (ret)
        return -EFAULT;

    return 0;
}

#include <linux/sched.h>
#include <linux/uaccess.h>

int set_extRegisters(struct task_struct *child, void __user *uregs)
{
    int ret;

    if (!uregs)
        return -EFAULT;

    /* Flush and release coprocessors if applicable */
    unlazy_fpu(child);

    ret = copy_from_user(&child->thread.ext_regs, uregs, sizeof(child->thread.ext_regs));
    if (ret)
        return -EFAULT;

    return 0;
}
